export const storyEn: Record<string, string> = {
  'story.avenida-atm.0.speaker': 'ATM Hacker',
  'story.avenida-atm.0.text':
    'Cage uplink’s live. Casa ATMs round down to the centavo and pocket the drift. Trigger the glitch before lockout.',
  'story.avenida-atm.1.speaker': 'Rita Odds',
  'story.avenida-atm.1.text': 'Every chipped coin buys time. Run the exploit.',
  'story.avenida-atm.2.speaker': 'ATM Hacker',
  'story.avenida-atm.2.text':
    'Machine’s south of the glass strip — away from Margin’s coffee. Don’t mix my glitch with his hearing.',
  'story.avenida-atm.title': 'ATM glitch hunt',
  'story.avenida-betrayal.0.speaker': 'Mole Contact',
  'story.avenida-betrayal.0.text':
    'Stop. The “leak” was never Luna’s alone — I sold a slice back to Casa for a clean exit. Your hill bytes have a mole scar.',
  'story.avenida-betrayal.1.speaker': 'Rita Odds',
  'story.avenida-betrayal.1.text':
    'You used us. The antenna, the pendrive, the fair — all so Augusto could watch the script?',
  'story.avenida-betrayal.2.choice.0.label': 'Keep Luna close',
  'story.avenida-betrayal.2.choice.0.reply':
    'Luna stays. The mole burns. We walk into Margin with receipts, not revenge.',
  'story.avenida-betrayal.2.choice.1.label': 'Cut soft allies',
  'story.avenida-betrayal.2.choice.1.reply':
    'I cut soft allies. Only cold ledger walks into that hearing.',
  'story.avenida-betrayal.2.speaker': 'Mole Contact',
  'story.avenida-betrayal.2.text':
    'Call it. Skill read: who sold the hill’s bytes? Clue’s in who still picks up for Casa without leaving a name. Your choice after still matters at Margin’s table.',
  'story.avenida-betrayal.3.speaker': 'Mole Contact',
  'story.avenida-betrayal.3.text':
    'Either way, Margin’s coffee is next. Win the testimony — the tower unlocks.',
  'story.avenida-betrayal.title': 'Betrayal on the boulevard',
  'story.avenida-checkpoint.0.speaker': 'Captain Vespera',
  'story.avenida-checkpoint.0.text':
    'Papers and chips. No odd, no passage. Or… paint the facade and prove you’ve got street blood.',
  'story.avenida-checkpoint.1.speaker': 'Rita Odds',
  'story.avenida-checkpoint.1.text':
    'I’ll take pixo over a stamp. The boulevard already chose a side.',
  'story.avenida-checkpoint.2.speaker': 'Captain Vespera',
  'story.avenida-checkpoint.2.text':
    'Then wager the spray. Win and the militia looks the other way — for a block.',
  'story.avenida-checkpoint.title': "Captain's checkpoint",
  'story.avenida-courier.0.speaker': 'Casa Courier',
  'story.avenida-courier.0.text':
    'Capita waved you through. Shadow me through the alleys — I drop VIP chip routes if you keep up.',
  'story.avenida-courier.1.speaker': 'Rita Odds',
  'story.avenida-courier.1.text': 'Chase, not coin flip. Lead.',
  'story.avenida-courier.2.speaker': 'Casa Courier',
  'story.avenida-courier.2.text':
    'Four alleys. Miss a turn and you tip the stake — then the influencer still waits east.',
  'story.avenida-courier.title': 'Courier shadow',
  'story.avenida-drone.0.speaker': 'Neon Snap',
  'story.avenida-drone.0.text':
    'Influencer’s feed cooked the airspace. Militia drones paint cones on the asphalt.',
  'story.avenida-drone.1.speaker': 'Rita Odds',
  'story.avenida-drone.1.text': 'I don’t walk into light. Show me the blind path.',
  'story.avenida-drone.2.choice.0.label': 'Slip low — no photos',
  'story.avenida-drone.2.choice.0.reply':
    'Low and quiet. Snap stays offline until I’m clear.',
  'story.avenida-drone.2.choice.1.label': 'Dash loud — burn a flare',
  'story.avenida-drone.2.choice.1.reply':
    'Flare first. If they chase the light, I own the dark.',
  'story.avenida-drone.2.speaker': 'Neon Snap',
  'story.avenida-drone.2.text':
    'Hug the glass shadow. Cut when the cone blinks. Miss a step and the sweep tags you.',
  'story.avenida-drone.3.speaker': 'Neon Snap',
  'story.avenida-drone.3.text':
    'Either way — Mensageiro’s waiting once the cones go dark.',
  'story.avenida-drone.title': 'Drone cones on the boulevard',
  'story.avenida-influencer.0.speaker': 'Odds Influencer',
  'story.avenida-influencer.0.text':
    'Live from Odds Avenue! Casa pays me per view. Call the fake engagement — skill read, not a roll.',
  'story.avenida-influencer.1.speaker': 'Rita Odds',
  'story.avenida-influencer.1.text':
    'Your numbers spike overnight — bought likes. Real hill tags don’t jump like that, and this isn’t a Casa promo.',
  'story.avenida-influencer.2.speaker': 'Odds Influencer',
  'story.avenida-influencer.2.text':
    'Cute read. Prove it on the panel before my next filter drop.',
  'story.avenida-influencer.title': 'Influencer duel',
  'story.avenida-radar.0.speaker': 'Mensageiro',
  'story.avenida-radar.0.text': 'Drones blinked. Radar vans still circle the ATM strip.',
  'story.avenida-radar.1.speaker': 'Rita Odds',
  'story.avenida-radar.1.text': 'I don’t wait for vans. I time them.',
  'story.avenida-radar.2.speaker': 'Mensageiro',
  'story.avenida-radar.2.text':
    'West-to-east sweep. When it clears, cut south off asphalt to the cage — then the ATM.',
  'story.avenida-radar.3.speaker': 'Rita Odds',
  'story.avenida-radar.3.text': 'Sweep, then south. Got it.',
  'story.avenida-radar.title': 'Neon radar shop',
  'story.avenida-server.0.speaker': 'Cage Runner',
  'story.avenida-server.0.text':
    'Militia vans cleared. There’s a Casa server cage off the glass strip — four tumblers, one quiet minute.',
  'story.avenida-server.1.speaker': 'Rita Odds',
  'story.avenida-server.1.text':
    'Infiltration, not a coin flip. If I crack it, the ATM glitch gets a clean uplink.',
  'story.avenida-server.2.choice.0.label': 'Pull the pit mirror files',
  'story.avenida-server.2.choice.0.reply':
    'Mirror the pit. Augusto’s private rake tables come with me.',
  'story.avenida-server.2.choice.1.label': 'Plant a deadman’s beacon',
  'story.avenida-server.2.choice.1.reply':
    'Beacon planted. If the hearing stalls, the feed still screams.',
  'story.avenida-server.2.speaker': 'Cage Runner',
  'story.avenida-server.2.text':
    'Clue’s etched under the latch. Set every pin, submit once. Miss and tip the stake — same cage, same pins.',
  'story.avenida-server.3.speaker': 'Cage Runner',
  'story.avenida-server.3.text':
    'After the cage, the ATM hacker waits south. Don’t linger — cams wake on a bad pin.',
  'story.avenida-server.title': 'Server-cage infiltration',
  'story.avenida-stealth.0.speaker': 'Lobby Cam Tech',
  'story.avenida-stealth.0.text':
    'ATM glitch woke the lobby cams. Slip the routes before Margin’s hearing — five quiet steps.',
  'story.avenida-stealth.1.speaker': 'Rita Odds',
  'story.avenida-stealth.1.text': 'Stealth chase. No dice. Walk me through.',
  'story.avenida-stealth.2.speaker': 'Lobby Cam Tech',
  'story.avenida-stealth.2.text':
    'Miss a step and you tip the stake. Then the betrayal meet — then coffee with Margin.',
  'story.avenida-stealth.title': 'Lobby cam slip',
  'story.avenida-twist.0.speaker': 'Mole Contact',
  'story.avenida-twist.0.text':
    'Your “leak” smells like Casa bait. I heard whispers — could be a mole feeding Luna bad bytes.',
  'story.avenida-twist.1.speaker': 'Rita Odds',
  'story.avenida-twist.1.text':
    'Luna wouldn’t… would she? I need truth before I march on the boulevard.',
  'story.avenida-twist.2.speaker': 'Mole Contact',
  'story.avenida-twist.2.text':
    'Bet the twist. Win and we know if the vazamento is real. Lose and assume the corp wrote the script.',
  'story.avenida-twist.3.speaker': 'Rita Odds',
  'story.avenida-twist.3.text':
    'If it’s bait, I still walk the boulevard. Truth or trap — I need eyes on Capita’s checkpoint next.',
  'story.avenida-twist.4.speaker': 'Mole Contact',
  'story.avenida-twist.4.text':
    'Whatever you decide, don’t tell the influencer. Their glow’s on Casa payroll.',
  'story.avenida-twist.title': 'Leak or plant?',
  'story.bia-set.0.speaker': 'Bia Forró',
  'story.bia-set.0.text':
    'If the bass doesn’t shake the laje, the revolution won’t stick. Time the samba against the corp jingle — no dice.',
  'story.bia-set.1.choice.0.label': 'Dance with the crowd',
  'story.bia-set.1.choice.0.reply':
    'I move with them. If Casa wants a meter, they’ll count feet.',
  'story.bia-set.1.choice.1.label': 'Watch from the rail',
  'story.bia-set.1.choice.1.reply':
    'I’ll read the floor from the rail. Someone has to clock the militia.',
  'story.bia-set.1.speaker': 'Rita Odds',
  'story.bia-set.1.text': 'Needle on the downbeat. Tonight the floor is ours.',
  'story.bia-set.2.speaker': 'Bia Forró',
  'story.bia-set.2.text':
    'After the set, catch Dancer Sol’s cue — then the DJ. He reads the crowd better than any Casa sensor.',
  'story.bia-set.title': 'Pirate synth-forró set',
  'story.boteco-nair.0.speaker': 'Dona Nair',
  'story.boteco-nair.0.text':
    'E aí, Rita? Face of someone who owes the corp. Want water? You have to bet — city law.',
  'story.boteco-nair.1.choice.0.label': 'Loud — then Take the bet',
  'story.boteco-nair.1.choice.0.reply':
    'Loud it is. Style’s locked — next tap Take the bet for the ice pour. No more looping the menu.',
  'story.boteco-nair.1.choice.1.label': 'Quiet — then Take the bet',
  'story.boteco-nair.1.choice.1.reply':
    'Quiet. Style’s locked — next tap Take the bet for the ice pour. The choices won’t come back.',
  'story.boteco-nair.1.speaker': 'Rita Odds',
  'story.boteco-nair.1.text':
    'What a country. Hit me with the ice-water odd — I’ll time the pour myself.',
  'story.boteco-nair.2.speaker': 'Dona Nair',
  'story.boteco-nair.2.text':
    'Either way, the ice odd is the door. Win the pour and Catador weighs copper — miss and you retry with me. Nothing advances until the ice lands.',
  'story.boteco-nair.3.speaker': 'Dona Nair',
  'story.boteco-nair.3.text':
    'Luna’s been sniffing around the LED antenna. Pirate signal nonsense. Drink slow. Casa bills the ice cubes now.',
  'story.boteco-nair.title': "Dona Nair's boteco",
  'story.epilogue-laje.0.speaker': 'Dona Nair',
  'story.epilogue-laje.0.text':
    'Rita. Sit. The ice is honest tonight — no odd attached. You walked the hill, the fair, the avenue, and you made Augusto sweat.',
  'story.epilogue-laje.1.speaker': 'Capitã',
  'story.epilogue-laje.1.text':
    '(radio crackle) Hill’s clear. Antenna still sings your pirate hymn. Don’t forget who kept the splice warm.',
  'story.epilogue-laje.2.speaker': 'Fio',
  'story.epilogue-laje.2.text':
    'And who ran the lajes when the cams blinked. Your chase steps still echo on my tiles.',
  'story.epilogue-laje.3.speaker': 'Luna',
  'story.epilogue-laje.3.text':
    'Pendrive’s archived. Pit ledger’s public. Casa can rebuild — we’ll have the receipts.',
  'story.epilogue-laje.4.speaker': 'Rita Odds',
  'story.epilogue-laje.4.text':
    'He called it skill. I called it the city. The ledger still has names, but they’re ours now.',
  'story.epilogue-laje.5.choice.0.label': 'Keep the pirate feed warm',
  'story.epilogue-laje.5.choice.0.reply':
    'Feed stays warm. When Casa rebuilds, the hill hears first.',
  'story.epilogue-laje.5.choice.1.label': 'Rest the odds — free roam',
  'story.epilogue-laje.5.choice.1.reply':
    'Odds can rest. Side hustles stay optional. Neon can wait.',
  'story.epilogue-laje.5.speaker': 'Dona Nair',
  'story.epilogue-laje.5.text':
    'One last call from the boteco — how do you leave the table?',
  'story.epilogue-laje.6.speaker': 'Dona Nair',
  'story.epilogue-laje.6.text':
    'Saúde. The credits roll for everyone who bet with you — then the city is yours again.',
  'story.epilogue-laje.title': 'Epilogue on the laje',
  'story.feira-catador.0.speaker': 'Catador da Feira',
  'story.feira-catador.0.text':
    'Corp bottle deposit pays pennies. I bet the sack weight — you help me sift the plaza before militia sweeps.',
  'story.feira-catador.1.speaker': 'Rita Odds',
  'story.feira-catador.1.text': 'Fine. If your pile hits quota, what do I get?',
  'story.feira-catador.2.speaker': 'Catador da Feira',
  'story.feira-catador.2.text':
    'Rumor Bia’s forró set is tonight. Win the garrafa odd and I point you to the speakers.',
  'story.feira-catador.title': 'Bottle scavenger',
  'story.feira-courier.0.speaker': 'Lavador da Feira',
  'story.feira-courier.0.text':
    'Tia cleared the wired crate. Luna’s waiting with the pendrive — militia still sniffs USB heat.',
  'story.feira-courier.1.speaker': 'Rita Odds',
  'story.feira-courier.1.text': 'Then I need a clean walk to her. Any cover?',
  'story.feira-courier.2.speaker': 'Lavador da Feira',
  'story.feira-courier.2.text':
    'Stay on the asphalt strip mid-fair — cyan hair by the radio crates, same lane. Don’t climb the stalls.',
  'story.feira-courier.3.speaker': 'Rita Odds',
  'story.feira-courier.3.text': 'Asphalt mid-fair, cyan hair. Got it.',
  'story.feira-courier.4.speaker': 'Lavador da Feira',
  'story.feira-courier.4.text':
    'When you’re done, the east exit on this same strip goes to Odds Avenue — once Luna’s file unlocks it.',
  'story.feira-courier.title': 'Calçadão courier tip',
  'story.feira-dancer.0.speaker': 'Dancer Sol',
  'story.feira-dancer.0.text':
    'Bia warmed the square. Catch my cue beat before the corp playlist hijacks the speakers.',
  'story.feira-dancer.1.speaker': 'Rita Odds',
  'story.feira-dancer.1.text': 'Timing, not luck. Show me the window.',
  'story.feira-dancer.2.speaker': 'Dancer Sol',
  'story.feira-dancer.2.text':
    'Green zone mid-spin. Miss and you tip the stake — try again. Then hit the DJ.',
  'story.feira-dancer.title': 'Dancer’s cue',
  'story.feira-forro.0.speaker': 'DJ Forró',
  'story.feira-forro.0.text':
    'Corpo wants a static crowd — easy to count, easy to tax. Bet whether this square erupts into dance.',
  'story.feira-forro.1.speaker': 'Rita Odds',
  'story.feira-forro.1.text':
    'If the calçadão moves, militia gets nervous. I’m wagering on sweat and sax.',
  'story.feira-forro.2.speaker': 'DJ Forró',
  'story.feira-forro.2.text':
    'Party peaks, Luna slides the pendrive handoff. Miss the beat and we try again.',
  'story.feira-forro.title': 'Crowd surge on the calçadão',
  'story.feira-kiko.0.speaker': 'Kiko Calçadão',
  'story.feira-kiko.0.text':
    'Olha o pastel! Olha a odd! The calçadão shines like Copacabana, except every stone is a market.',
  'story.feira-kiko.1.speaker': 'Rita Odds',
  'story.feira-kiko.1.text': 'I need Odds Avenue. The Casa is hiding the code.',
  'story.feira-kiko.2.speaker': 'Kiko Calçadão',
  'story.feira-kiko.2.text':
    'Talk to the catador by the stalls. He sees everything tossed in the calçadão trash.',
  'story.feira-kiko.3.speaker': 'Rita Odds',
  'story.feira-kiko.3.text':
    'Fair ground smells like oil and guaraná. Keep me pointed at the scavenger.',
  'story.feira-kiko.title': 'Sidewalk of odds',
  'story.feira-lockbox.0.speaker': 'Stage Hand',
  'story.feira-lockbox.0.text': 'Forró shook a Casa lockbox loose under the risers.',
  'story.feira-lockbox.1.speaker': 'Stage Hand',
  'story.feira-lockbox.1.text':
    'Militia reclaim it after the set — unless you pick it first.',
  'story.feira-lockbox.2.speaker': 'Rita Odds',
  'story.feira-lockbox.2.text': 'Tumblers, not dice. What’s inside?',
  'story.feira-lockbox.3.choice.0.label': 'Crack it for the hill',
  'story.feira-lockbox.3.choice.0.reply':
    'Chips for the hill. Calçadão laughs louder than Casa.',
  'story.feira-lockbox.3.choice.1.label': 'Crack it for leverage',
  'story.feira-lockbox.3.choice.1.reply':
    'Leverage first. I’ll spend the chips when Augusto blinks.',
  'story.feira-lockbox.3.speaker': 'Stage Hand',
  'story.feira-lockbox.3.text':
    'Ledger chips. Spare keycard. Scratched plate lies — timer’s real, pick can snap.',
  'story.feira-lockbox.4.speaker': 'Stage Hand',
  'story.feira-lockbox.4.text':
    'Either score feeds the radio pirate next. Don’t trust the red sticker.',
  'story.feira-lockbox.title': 'Casa lockbox under the stage',
  'story.feira-radio.0.speaker': 'Radio Pirate',
  'story.feira-radio.0.text':
    'Forró’s shaking the meters. My pirate stack needs one more odd — bet the next track jumps the Casa noise filter.',
  'story.feira-radio.1.speaker': 'Rita Odds',
  'story.feira-radio.1.text':
    'If the filter trips, militia hears static instead of Luna’s handoff. I’m in.',
  'story.feira-radio.2.speaker': 'Radio Pirate',
  'story.feira-radio.2.text':
    'Win and the calçadão stays loud for ten quiet minutes. Lose and we sweat the sniffer vans.',
  'story.feira-radio.3.speaker': 'Rita Odds',
  'story.feira-radio.3.text': 'Ten minutes is enough. Roll it.',
  'story.feira-radio.title': 'Pirate radio odds',
  'story.feira-tipster.0.speaker': 'Barraca Tia',
  'story.feira-tipster.0.text':
    'Radio’s loud, kid. Before you chase pendrives — a tip: Casa pays snitches in mango crates. Want to bet which crate’s wired?',
  'story.feira-tipster.1.speaker': 'Rita Odds',
  'story.feira-tipster.1.text':
    'I’d rather not eat a tracker. Point me at the clean one.',
  'story.feira-tipster.2.speaker': 'Barraca Tia',
  'story.feira-tipster.2.text':
    'One crate baked by sun (sol), one that sings (canta) in the palm, one hollow (vazia). Place the odd — then Lavador will walk you to Luna.',
  'story.feira-tipster.3.speaker': 'Rita Odds',
  'story.feira-tipster.3.text': 'I’ll take the one that sings. After this, asphalt only.',
  'story.feira-tipster.title': 'Tipster at the mango crates',
  'story.intro-laje.0.speaker': 'Rita Odds',
  'story.intro-laje.0.text':
    'Another day, another odd. Even the sun over Morro Neon looks sponsored.',
  'story.intro-laje.1.speaker': 'Rita Odds',
  'story.intro-laje.1.text':
    'My debt to Casa Suprema is due at midnight. I need a plan — or a miracle.',
  'story.intro-laje.title': 'Wake up on the laje',
  'story.lobby-margin.0.speaker': 'Dr. Margin',
  'story.lobby-margin.0.text':
    'Regulation is just another table. Want a public hearing? Pick the testimony that sticks — skill read.',
  'story.lobby-margin.1.speaker': 'Rita Odds',
  'story.lobby-margin.1.text':
    'People will see the house edge eating schools, hospitals, and water. And the mole scar on our own bytes.',
  'story.lobby-margin.2.speaker': 'Dr. Margin',
  'story.lobby-margin.2.text':
    'The hearing decides everything. Place your chips — win, and the scandal trends citywide.',
  'story.lobby-margin.3.speaker': 'Rita Odds',
  'story.lobby-margin.3.text':
    'Then I buy the mic back with scandal. Let’s open the books.',
  'story.lobby-margin.title': 'Coffee with Dr. Margin',
  'story.luna-beco.0.speaker': 'Luna Pixel',
  'story.luna-beco.0.text':
    'Rita… I pulled a slice of their algorithm. But Seu Zé only trades the pendrive if you beat the rooftop draw.',
  'story.luna-beco.1.speaker': 'Rita Odds',
  'story.luna-beco.1.text':
    'Street lotteries got wiped when the corps took over. Now even the laje plays by Casa rules.',
  'story.luna-beco.2.speaker': 'Luna Pixel',
  'story.luna-beco.2.text':
    'Seu Zé’s booth sits east of the stairs. Don’t let Fio snatch the copper mid-hand — he runs the wires.',
  'story.luna-beco.title': 'Pixo alley',
  'story.morro-antena.0.speaker': 'Antena Tech',
  'story.morro-antena.0.text':
    'Copper’s in. Casa chopped the hill’s Wi‑Fi and sold it back drip by drip. Match my splice tones — no dice.',
  'story.morro-antena.1.speaker': 'Rita Odds',
  'story.morro-antena.1.text':
    'So I fund the splice, you hold the cable. Fair. Let’s hear if this hill still talks.',
  'story.morro-antena.2.speaker': 'Antena Tech',
  'story.morro-antena.2.text':
    'Signal’s clean, you catch Luna on the beco. Wipe the sequence and I kill the feed — not you.',
  'story.morro-antena.3.speaker': 'Rita Odds',
  'story.morro-antena.3.text': 'Pirate feed tastes like static and hope. Jack it.',
  'story.morro-antena.title': 'Jack the LED antenna',
  'story.morro-fios.0.speaker': 'Fio Ladrão',
  'story.morro-fios.0.text':
    'Your chip’s on my line, oddsmom. I sprint the lajes faster than Casa billing.',
  'story.morro-fios.1.speaker': 'Rita Odds',
  'story.morro-fios.1.text':
    'Thief! Every meter of copper on this hill is community property.',
  'story.morro-fios.2.speaker': 'Fio Ladrão',
  'story.morro-fios.2.text':
    'Bet the chase. Catch me and Seu Zé gets his wire back. Lose and I vanish into the neon.',
  'story.morro-fios.title': 'Wire chase on the lajes',
  'story.morro-return-fio.0.speaker': 'Fio Ladrão',
  'story.morro-return-fio.0.text':
    'Tower’s open and you’re sniffing copper again. I can ghost you a private line past security — for a price.',
  'story.morro-return-fio.1.speaker': 'Rita Odds',
  'story.morro-return-fio.1.text':
    'A private line means fewer people know. Safer — or lonelier.',
  'story.morro-return-fio.2.speaker': 'Fio Ladrão',
  'story.morro-return-fio.2.text':
    'Bet the splice. Win and you climb alone. Nair’s path is the loud one if you prefer company.',
  'story.morro-return-fio.3.speaker': 'Rita Odds',
  'story.morro-return-fio.3.text':
    'Company or silence — I still walk the asphalt myself. Place it.',
  'story.morro-return-fio.title': 'Return: cut a private wire',
  'story.morro-return-nair.0.speaker': 'Dona Nair',
  'story.morro-return-nair.0.text':
    'Scandal’s trending and you’re back for water. Good. The hill decides who walks into that tower.',
  'story.morro-return-nair.1.speaker': 'Rita Odds',
  'story.morro-return-nair.1.text':
    'Luna’s file, Fio’s wires, your ice — all of it. I need the hill behind me.',
  'story.morro-return-nair.2.speaker': 'Dona Nair',
  'story.morro-return-nair.2.text':
    'Bet that the lajes hold. Win and we back you. Or talk to Fio if you’d rather cut your own deal.',
  'story.morro-return-nair.3.speaker': 'Rita Odds',
  'story.morro-return-nair.3.text': 'I’m not cutting the hill out. Place it.',
  'story.morro-return-nair.4.speaker': 'Dona Nair',
  'story.morro-return-nair.4.text':
    'Either way: west exit stays Morro, east through Fair then Avenue. The tower doesn’t open for tourists.',
  'story.morro-return-nair.title': 'Return: trust the hill',
  'story.prova-luna.0.speaker': 'Luna Pixel',
  'story.prova-luna.0.text':
    'While the party rolls, we slip the leak through. Bet whether the file opens.',
  'story.prova-luna.1.speaker': 'Rita Odds',
  'story.prova-luna.1.text':
    'If it opens, Odds Avenue is next — and I’m bringing the whole city on my back.',
  'story.prova-luna.title': 'Pendrive on a freela',
  'story.seu-ze-banca.0.speaker': 'Seu Zé',
  'story.seu-ze-banca.0.text':
    'Everything’s licensed now, kid. Want Luna’s chip? Clear my moto gate on the laje first.',
  'story.seu-ze-banca.1.speaker': 'Rita Odds',
  'story.seu-ze-banca.1.text':
    'Deal. I’ll take the lane — pay out and point me to the Fair.',
  'story.seu-ze-banca.2.speaker': 'Seu Zé',
  'story.seu-ze-banca.2.text': 'Pode crer. Win first — routes come after.',
  'story.seu-ze-banca.title': "Seu Zé's booth",
  'story.side-avenida-neon.0.speaker': 'Neon Snap',
  'story.side-avenida-neon.0.text':
    'Corp billboards pay per fake smile. Bet whether street neon outshines their LED.',
  'story.side-avenida-neon.1.speaker': 'Rita Odds',
  'story.side-avenida-neon.1.text': 'Street light never needed a sponsor. Roll it.',
  'story.side-avenida-neon.title': 'Neon photo odd',
  'story.side-feira-ice.0.speaker': 'Kiko Calçadão',
  'story.side-feira-ice.0.text':
    'Ice cart’s late and the pastel oil’s hot. Bet whether the blocks show before the fryer dies.',
  'story.side-feira-ice.1.speaker': 'Rita Odds',
  'story.side-feira-ice.1.text': 'Hot oil, cold wager. Fine.',
  'story.side-feira-ice.title': 'Ice cart odd',
  'story.side-feira-mango.0.speaker': 'Barraca Tia',
  'story.side-feira-mango.0.text':
    'Mangoes or moths — tonight’s crate is a gamble. Small stake, sweet payout.',
  'story.side-feira-mango.1.speaker': 'Rita Odds',
  'story.side-feira-mango.1.text': 'If it’s ripe, I’m buying. If not, I’m learning.',
  'story.side-feira-mango.title': 'Mango stall odd',
  'story.side-morro-copper.0.speaker': 'Catador do Morro',
  'story.side-morro-copper.0.text':
    'Nair said you’d come. Spare wire on the lower laje — weigh the bright bag, not the rust.',
  'story.side-morro-copper.1.speaker': 'Rita Odds',
  'story.side-morro-copper.1.text': 'Skill check, not a coin flip. Point me at the bags.',
  'story.side-morro-copper.2.speaker': 'Catador do Morro',
  'story.side-morro-copper.2.text':
    'Win and Antena Tech will talk. Lose and you still owe the stake — try again with clearer eyes.',
  'story.side-morro-copper.title': 'Spare copper odd',
  'story.side-morro-tank.0.speaker': 'Antena Tech',
  'story.side-morro-tank.0.text':
    'Tank’s half empty again. Bet whether tonight’s refill arrives before the hill wakes thirsty.',
  'story.side-morro-tank.1.speaker': 'Rita Odds',
  'story.side-morro-tank.1.text': 'Water shouldn’t be a wager. Tonight it is — place it.',
  'story.side-morro-tank.title': 'Water tank odd',
  'story.side-torre-tip.0.speaker': 'Busboy',
  'story.side-torre-tip.0.text':
    'High rollers tip in chips that “fall.” Bet you can pocket one before cameras blink.',
  'story.side-torre-tip.1.speaker': 'Rita Odds',
  'story.side-torre-tip.1.text': 'Quiet hand, quiet exit. Let’s see.',
  'story.side-torre-tip.title': 'Dealer tip odd',
  'story.torre-elevator.0.speaker': 'Elevator',
  'story.torre-elevator.0.text':
    'VIP’s upstairs. Time the express call — green zone — then I carry you up. No coin flip.',
  'story.torre-elevator.1.speaker': 'Rita Odds',
  'story.torre-elevator.1.text': 'I’ve climbed worse stairs. Call the car.',
  'story.torre-elevator.2.speaker': 'Elevator',
  'story.torre-elevator.2.text':
    'Nail the timing and the doors open on chrome with a fade. Miss and you tip the stake — try again.',
  'story.torre-elevator.3.speaker': 'Rita Odds',
  'story.torre-elevator.3.text': 'Chrome or retry — I’m going up. Call it.',
  'story.torre-elevator.title': 'Elevator call',
  'story.torre-final.0.speaker': 'Augusto Casa',
  'story.torre-final.0.text': 'All of Brazil is my casino. You’re just another chip.',
  'story.torre-final.1.speaker': 'Rita Odds',
  'story.torre-final.1.text':
    'A chip? I’m the hill, the fair, the calçadão, and the pixo. Three phases — needle, read, terminal.',
  'story.torre-final.2.speaker': 'Augusto Casa',
  'story.torre-final.2.text':
    'Skill won’t save you from the house. Three phases. Miss one and you retry it — the stake waits for a full clear.',
  'story.torre-final.3.speaker': 'Rita Odds',
  'story.torre-final.3.text': 'Good. I’m done rolling your dice. Deal the city.',
  'story.torre-final.title': 'Duel at Casa Suprema Tower',
  'story.torre-foyer.0.speaker': 'Foyer Guard',
  'story.torre-foyer.0.text':
    'Badge or bet. Casa doesn’t let street odds into the pit for free.',
  'story.torre-foyer.1.speaker': 'Rita Odds',
  'story.torre-foyer.1.text': 'I brought scandal and a hill. That badge enough?',
  'story.torre-foyer.2.speaker': 'Foyer Guard',
  'story.torre-foyer.2.text':
    'Cute. Wager the bluff. Win and the velvet rope lifts. Lose and you wait with the tourists.',
  'story.torre-foyer.3.speaker': 'Rita Odds',
  'story.torre-foyer.3.text': 'I’m done waiting. Place it.',
  'story.torre-foyer.title': 'Foyer badge check',
  'story.torre-negotiate.0.speaker': 'VIP Host',
  'story.torre-negotiate.0.text':
    'Rake’s skimmed. I can still walk you out smiling — or with paper that burns.',
  'story.torre-negotiate.1.speaker': 'Rita Odds',
  'story.torre-negotiate.1.text': 'Name your price. Timer’s already on your face.',
  'story.torre-negotiate.2.choice.0.label': 'Take the hush chip',
  'story.torre-negotiate.2.choice.0.reply':
    'Hush chip in the pocket. Quiet doors. Thin leverage.',
  'story.torre-negotiate.2.choice.1.label': 'Demand the pit mirror',
  'story.torre-negotiate.2.choice.1.reply':
    'Host hardens. Mirror talk belongs in the books, not this handshake.',
  'story.torre-negotiate.2.choice.2.label': 'Walk out smiling',
  'story.torre-negotiate.2.choice.2.reply':
    'Cameras eat the smile. No chip. No deal. Try again when you’re quiet.',
  'story.torre-negotiate.2.speaker': 'VIP Host',
  'story.torre-negotiate.2.text':
    'Three offers. One sticks. Augusto hears whatever you leave on the table.',
  'story.torre-negotiate.3.speaker': 'VIP Host',
  'story.torre-negotiate.3.text':
    'Deal’s sealed. Clear path to Augusto — hold his eye, don’t blink first.',
  'story.torre-negotiate.title': 'Negotiate the VIP exit',
  'story.torre-pit.0.speaker': 'Pit Dealer',
  'story.torre-pit.0.text':
    'VIP’s upstairs, but the pit wants a warm-up hand. Spot the real deck — my thumb keeps returning to one soft corner; foil shine and plastic wrap are show props.',
  'story.torre-pit.1.speaker': 'Rita Odds',
  'story.torre-pit.1.text': 'Convert, then. One clean hand before the high rollers.',
  'story.torre-pit.2.speaker': 'Pit Dealer',
  'story.torre-pit.2.text':
    'Cards are marked in three places. Bet you spot the real deck before the floor manager does.',
  'story.torre-pit.3.speaker': 'Rita Odds',
  'story.torre-pit.3.text': 'I grew up reading marked asphalt. Deal.',
  'story.torre-pit.title': 'Pit floor warm-up',
  'story.torre-vip.0.speaker': 'VIP Host',
  'story.torre-vip.0.text': 'Elevator spit you out clean. High rollers want a show.',
  'story.torre-vip.1.speaker': 'Rita Odds',
  'story.torre-vip.1.text': 'One quiet hand. Then Augusto.',
  'story.torre-vip.2.speaker': 'VIP Host',
  'story.torre-vip.2.text':
    'Skim the rake before security blinks. After that — we talk terms.',
  'story.torre-vip.title': 'VIP floor',
  'story.torre-final.hush.speaker': 'Augusto Casa',
  'story.torre-final.hush.text':
    'That hush chip rattles in your pocket. Security already looked away — cheap courage before the duel.',
};
